function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit'
  }).format(date);
}

function esc(s) {
  return String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function fmtDate(v) {
  if (!v) return '-';
  const d = new Date(v);
  if (isNaN(d.getTime())) return '-';
  return d.toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}
function fmtDateOnly(v) {
  if (!v) return '-';
  const d = new Date(v);
  if (isNaN(d.getTime())) return String(v).slice(0, 10);
  return d.toISOString().slice(0, 10);
}

// alwaysOutputData:true auf den DB-Nodes liefert bei 0 Treffern ein Platzhalter-Item (sonst
// wuerde n8n die Folge-Nodes bei 0 Zeilen gar nicht erst ausfuehren) - anhand des jeweiligen
// Pflichtfelds herausfiltern (gleiches Prinzip wie in Workflow 15).
const jobs = $('DB: Jobs laden').all().map(i => i.json).filter(j => j && j.job_id);
const progressRows = $('DB: Job-Item-Fortschritt laden').all().map(i => i.json).filter(j => j && j.job_id);
const statsRows = $input.all().map(i => i.json).filter(j => j && j.import_job_id);

const progressByJob = {};
const scannedByJob = {};
for (const r of progressRows) {
  if (!progressByJob[r.job_id]) progressByJob[r.job_id] = {};
  progressByJob[r.job_id][r.status] = Number(r.anzahl);
  scannedByJob[r.job_id] = (scannedByJob[r.job_id] || 0) + Number(r.durchsucht || 0);
}
const statsByJob = {};
for (const r of statsRows) statsByJob[r.import_job_id] = r;

const STATUS_LABEL = {
  draft: 'Entwurf', queued: 'wartet', running: 'laeuft', pausing: 'pausiert (wird beendet)',
  paused: 'pausiert', completed: 'abgeschlossen', completed_with_warnings: 'abgeschlossen (mit Warnungen)',
  failed: 'fehlgeschlagen', cancelled: 'abgebrochen'
};

const jobsHtml = jobs.map(j => {
  const zeitraum = (j.period_from && j.period_to) ? (esc(fmtDateOnly(j.period_from)) + ' - ' + esc(fmtDateOnly(j.period_to))) : '-';
  const prog = progressByJob[j.job_id] || {};
  const done = (prog.completed || 0);
  const failed = (prog.failed || 0);
  const skipped = (prog.skipped || 0);
  const total = j.progress_total || 0;
  const pct = total > 0 ? Math.round(100 * (done + failed + skipped) / total) : 0;
  const stats = statsByJob[j.job_id] || {};
  const scanned = scannedByJob[j.job_id] || 0;
  const statusLabel = STATUS_LABEL[j.status] || esc(j.status);
  const canPause = ['queued', 'running'].includes(j.status);
  const canResume = j.status === 'paused';
  const canCancel = ['draft', 'queued', 'running', 'pausing', 'paused'].includes(j.status);
  const canRetry = failed > 0 && ['completed_with_warnings', 'failed'].includes(j.status);

  function actionForm(action, label) {
    return '<form method="post" action="/webhook/historische-nachrichten" style="display:inline;">' +
      '<input type="hidden" name="action" value="' + action + '">' +
      '<input type="hidden" name="job_id" value="' + esc(j.job_id) + '">' +
      '<button type="submit">' + label + '</button></form>';
  }

  return '<tr>' +
    '<td>' + esc(j.job_id) + '</td>' +
    '<td>' + zeitraum + '</td>' +
    '<td><span class="badge">' + statusLabel + '</span></td>' +
    '<td>' + done + '/' + total + ' Tage (' + pct + '%)' + (failed ? ', ' + failed + ' fehlgeschlagen' : '') + '</td>' +
    '<td>' + scanned.toLocaleString('de-DE') + ' durchsucht &middot; ' + (stats.anzahl || 0) + ' importiert (' + (stats.matched || 0) + ' zugeordnet, ' + (stats.ambiguous || 0) + ' mehrdeutig, ' + (stats.general_market || 0) + ' Markt/Makro)' + '</td>' +
    '<td>' + fmtDate(j.heartbeat_at) + '</td>' +
    '<td>' +
      (canPause ? actionForm('pause', 'Pausieren') : '') +
      (canResume ? actionForm('resume', 'Fortsetzen') : '') +
      (canCancel ? actionForm('cancel', 'Abbrechen') : '') +
      (canRetry ? actionForm('retry_failed', 'Fehlgeschlagene wiederholen') : '') +
    '</td>' +
  '</tr>';
}).join('');

const html = '<!DOCTYPE html><html lang="de"><head><meta charset="utf-8">' +
  '<title>Historische Nachrichten importieren (GDELT)</title>' +
  '<style>' +
  'body{font-family:sans-serif;background:#1a1a1a;color:#e0e0e0;padding:24px;}' +
  'h1{color:#fff;} table{border-collapse:collapse;width:100%;margin-top:12px;}' +
  'th,td{border:1px solid #444;padding:6px 10px;text-align:left;font-size:14px;}' +
  'th{background:#2a2a2a;} .badge{background:#333;padding:2px 8px;border-radius:4px;}' +
  'form.import-form{background:#232323;padding:16px;border-radius:8px;margin-bottom:24px;max-width:700px;}' +
  'label{display:block;margin-top:10px;font-size:13px;color:#aaa;}' +
  'input[type=date]{width:100%;padding:6px;background:#1a1a1a;color:#e0e0e0;border:1px solid #444;border-radius:4px;}' +
  'button{margin-top:12px;padding:8px 16px;background:#2d6cdf;color:#fff;border:none;border-radius:4px;cursor:pointer;}' +
  '.hint{font-size:12px;color:#888;margin-top:4px;}' +
  '</style></head><body>' +
  '<div style="background:#232323;border:1px solid #444;border-radius:6px;padding:8px 14px;margin-bottom:20px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;"><a href="/webhook/aktien-status" style="color:#8ab4f8;text-decoration:none;">Status</a><a href="/webhook/aktien-watchlist" style="color:#8ab4f8;text-decoration:none;">Watchlist</a><a href="/webhook/rss-quellen" style="color:#8ab4f8;text-decoration:none;">RSS-Quellen</a><a href="/webhook/lernvorschlaege" style="color:#8ab4f8;text-decoration:none;">Lernvorschlaege</a><a href="/webhook/historische-marktdaten" style="color:#8ab4f8;text-decoration:none;">Marktdaten-Import</a><a href="/webhook/historische-nachrichten" style="color:#8ab4f8;text-decoration:none;">Nachrichten-Import</a><a href="/webhook/historische-news-lernkandidaten" style="color:#8ab4f8;text-decoration:none;">News-Lernkandidaten</a><a href="/webhook/historische-news-ausschluesse" style="color:#8ab4f8;text-decoration:none;">Ausschlussregeln</a><a href="/webhook/historische-simulation" style="color:#8ab4f8;text-decoration:none;">Simulationslaeufe</a><a href="/webhook/simulation-lauf" style="color:#8ab4f8;text-decoration:none;">Simulation starten</a><a href="/webhook/simulation-uebersicht" style="color:#8ab4f8;text-decoration:none;">Sim-Uebersicht</a><a href="/webhook/simulation-vergleich" style="color:#8ab4f8;text-decoration:none;">Sim-Vergleich</a></div>' +
  '<h1>Historische Nachrichten importieren (GDELT)</h1>' +
  '<form class="import-form" method="post" action="/webhook/historische-nachrichten">' +
    '<input type="hidden" name="action" value="create_import">' +
    '<label>Startdatum</label>' +
    '<input type="date" name="period_from" required min="2020-01-01">' +
    '<div class="hint">GDELT Article List Historical Backfile deckt fruehestens 2020-01-01 ab.</div>' +
    '<label>Enddatum</label>' +
    '<input type="date" name="period_to" required>' +
    '<label><input type="checkbox" name="dry_run" value="true" style="width:auto;display:inline;"> Testlauf (prueft nur Erreichbarkeit, schreibt keine Daten)</label>' +
    '<button type="submit">Import starten</button>' +
  '</form>' +
  '<h2>Bisherige Importe</h2>' +
  '<table><tr><th>Job-ID</th><th>Zeitraum</th><th>Status</th><th>Fortschritt</th><th>Nachrichten</th><th>Letzter Heartbeat</th><th>Aktionen</th></tr>' +
  jobsHtml +
  '</table>' +
  '</body></html>';

return [{ json: { html } }];

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'[]'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }
function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit'
  }).format(date);
}

// Aktions-Whitelist-Pattern, identisch zu Workflow 15/"Watchlist verwalten". Zeitraum wird beim
// Job-Start in einzelne Tages-Items zerlegt (ein import_job_items-Item pro Kalendertag), NICHT
// pro 15-Minuten-Marke - siehe Konzeptdoc Abschnitt 4.2 Punkt 1 fuer die Begruendung.

const ALLOWED_ACTIONS = new Set(['create_import', 'pause', 'resume', 'cancel', 'retry_failed']);
const GDELT_EARLIEST = '2020-01-01';
const MAX_DAYS_PER_JOB = 3660; // ~10 Jahre Sicherheitsnetz gegen versehentlich riesige Jobs

const body = $input.item.json.body || $input.item.json;
const action = String(body.action || '').trim();

if (!ALLOWED_ACTIONS.has(action)) {
  return { json: { _error: 'Unbekannte Aktion: ' + action, sql: null } };
}

function randHex(n) {
  let s = '';
  for (let i = 0; i < n; i++) s += Math.floor(Math.random() * 16).toString(16);
  return s;
}

let sql = '';
let responseInfo = { action };

if (action === 'create_import') {
  const periodFrom = String(body.period_from || '').trim();
  const periodTo = String(body.period_to || '').trim();
  const dryRun = body.dry_run === 'true' || body.dry_run === true;

  if (!/^\d{4}-\d{2}-\d{2}$/.test(periodFrom) || !/^\d{4}-\d{2}-\d{2}$/.test(periodTo)) {
    return { json: { _error: 'Start-/Enddatum fehlt oder ungueltiges Format (YYYY-MM-DD).', sql: null } };
  }
  if (periodFrom < GDELT_EARLIEST) {
    return { json: { _error: 'GDELT Article List Historical Backfile deckt fruehestens ' + GDELT_EARLIEST + ' ab.', sql: null } };
  }
  if (periodTo < periodFrom) {
    return { json: { _error: 'Enddatum liegt vor dem Startdatum.', sql: null } };
  }

  const days = [];
  let cursor = new Date(periodFrom + 'T00:00:00Z');
  const end = new Date(periodTo + 'T00:00:00Z');
  while (cursor <= end && days.length < MAX_DAYS_PER_JOB) {
    days.push(cursor.toISOString().slice(0, 10));
    cursor = new Date(cursor.getTime() + 24 * 3600 * 1000);
  }
  if (cursor <= end) {
    return { json: { _error: 'Zeitraum zu gross (mehr als ' + MAX_DAYS_PER_JOB + ' Tage) - bitte in kleineren Abschnitten importieren.', sql: null } };
  }
  if (days.length === 0) {
    return { json: { _error: 'Zeitraum ergibt keine Tage.', sql: null } };
  }

  const jobId = 'newsimp-' + getBusinessDate() + '-' + randHex(6);

  const jobInsert = `INSERT INTO trading.import_jobs
    (job_id, job_type, status, provider, period_from, period_to, dry_run, progress_total)
    VALUES (${pgStr(jobId)}, 'news', 'queued', 'gdelt', ${pgStr(periodFrom)}, ${pgStr(periodTo)}, ${pgBool(dryRun)}, ${pgNum(days.length)});`;

  const itemValues = days.map((day, idx) =>
    `(${pgStr(jobId)}, ${pgNum(idx + 1)}, ${pgStr('GDELT-GLOBAL')}, ${pgStr(day)}, ${pgStr(day)}, 'pending', ${pgJsonb({ last_mark_index: -1, article_count: 0 })})`
  ).join(',\n    ');

  const itemsInsert = `INSERT INTO trading.import_job_items
    (job_id, sequence_number, instrument, period_from, period_to, status, checkpoint_json)
    VALUES\n    ${itemValues};`;

  sql = `BEGIN;\n${jobInsert}\n${itemsInsert}\nCOMMIT;`;
  responseInfo = { action, job_id: jobId, day_count: days.length, dry_run: dryRun };

} else if (action === 'pause') {
  const jobId = String(body.job_id || '').trim();
  if (!jobId) return { json: { _error: 'job_id fehlt.', sql: null } };
  sql = `BEGIN;\nUPDATE trading.import_jobs SET status = 'pausing' WHERE job_id = ${pgStr(jobId)} AND status IN ('queued','running');\nCOMMIT;`;
  responseInfo = { action, job_id: jobId };

} else if (action === 'resume') {
  const jobId = String(body.job_id || '').trim();
  if (!jobId) return { json: { _error: 'job_id fehlt.', sql: null } };
  sql = `BEGIN;\nUPDATE trading.import_jobs SET status = 'queued' WHERE job_id = ${pgStr(jobId)} AND status = 'paused';\nCOMMIT;`;
  responseInfo = { action, job_id: jobId };

} else if (action === 'cancel') {
  const jobId = String(body.job_id || '').trim();
  if (!jobId) return { json: { _error: 'job_id fehlt.', sql: null } };
  sql = `BEGIN;
UPDATE trading.import_jobs SET status = 'cancelled', finished_at = now() WHERE job_id = ${pgStr(jobId)} AND status IN ('draft','queued','running','pausing','paused');
UPDATE trading.import_job_items SET status = 'skipped' WHERE job_id = ${pgStr(jobId)} AND status IN ('pending','running');
COMMIT;`;
  responseInfo = { action, job_id: jobId };

} else if (action === 'retry_failed') {
  const jobId = String(body.job_id || '').trim();
  if (!jobId) return { json: { _error: 'job_id fehlt.', sql: null } };
  sql = `BEGIN;
UPDATE trading.import_job_items SET status = 'pending', error = NULL WHERE job_id = ${pgStr(jobId)} AND status = 'failed';
UPDATE trading.import_jobs SET status = 'queued' WHERE job_id = ${pgStr(jobId)} AND status IN ('completed_with_warnings','failed');
COMMIT;`;
  responseInfo = { action, job_id: jobId };
}

return { json: { sql, ...responseInfo } };

// "POST: SQL ausfuehren" (Postgres ohne RETURNING) ersetzt das Item-JSON durch sein eigenes
// Ergebnis - Antwortfelder deshalb vom SQL-Bauen-Node zurueckholen (gleiche Bugklasse wie in
// Workflow 15, siehe dortige Kommentare).
const original = $('POST: Formular normalisieren + SQL bauen').item.json;
const current = $json;

if (original._error) {
  return { json: { ok: false, error: original._error } };
}
if (current.error) {
  return { json: { ok: false, error: 'Datenbankfehler beim Ausfuehren der Aktion.', action: original.action, job_id: original.job_id } };
}
return { json: { ok: true, action: original.action, job_id: original.job_id, day_count: original.day_count, dry_run: original.dry_run } };

// Gleiches Muster wie Workflow 15: kein aktiver Job -> Ende. Pausierend -> auf 'paused' setzen
// + Ende. alwaysOutputData:true liefert bei 0 aktiven Jobs ein Platzhalter-Item ohne job_id.
const items = $input.all().filter(i => i.json && i.json.job_id);
if (items.length === 0) {
  return [{ json: { _kein_job: true } }];
}
const job = items[0].json;
return [{ json: { ...job, _kein_job: false, _job_pausierend: job.status === 'pausing' } }];

// Traegt Job-Daten und Konfigurationswerte zusammen, bevor das naechste Tages-Paket geladen wird.
const job = $('Pruefe Job-Zustand').all()[0].json;
const cfgRows = $input.all().map(i => i.json);
const cfgByKey = {};
for (const r of cfgRows) cfgByKey[r.config_key] = r.value_numeric !== null && r.value_numeric !== undefined ? Number(r.value_numeric) : r.value_text;
// FIX 2026-08-17 (2. Iteration): erst adaptive Batchgroesse gebaut (siehe Git-Historie), dann
// Nutzer-Entscheidung dagegen - einfacher und mit noch weniger Crash-Risiko: IMMER nur 1 Marke
// pro Tick (siehe "Baue Marken-Kandidaten"), dafuer feuert der Trigger alle 15s statt alle 6min.
// Laeuft der vorherige Tick noch, findet ein zu frueher Trigger dank "FOR UPDATE SKIP LOCKED" in
// "DB: Naechstes Tages-Paket laden" einfach kein beanspruchbares Item und beendet sich als No-Op
// - das Tempo stellt sich dadurch von selbst auf die tatsaechliche Verarbeitungsdauer ein.
return [{ json: {
  ...job,
  _probe_window_min: cfgByKey.GDELT_PROBE_WINDOW_MINUTES || 5,
  _request_delay_ms: cfgByKey.GDELT_REQUEST_DELAY_MS || 1500,
  _max_retries: cfgByKey.IMPORT_MAX_RETRY_ATTEMPTS || 3
} }];

// Kein offenes Tages-Item mehr -> Job abschliessen. Sonst: Tages-Item zur Verarbeitung
// weiterreichen. alwaysOutputData:true liefert bei 0 offenen Items ein Platzhalter-Item ohne id.
const job = $('Baue Tick-Kontext').all()[0].json;
const items = $input.all().map(i => i.json).filter(j => j && j.id !== undefined && j.id !== null);
if (items.length === 0) {
  return [{ json: { _placeholder: true, job_id: job.job_id } }];
}
const it = items[0];
return [{ json: { ...it, _job_id: job.job_id, _max_retries: job._max_retries, _probe_window_min: job._probe_window_min, _request_delay_ms: job._request_delay_ms, _dry_run: job.dry_run === true } }];

// Baut fuer diesen Worker-Tick die Liste der zu probierenden GDELT-Dateikandidaten.
// Ein Tag hat 96 Viertelstunden-Marken (0..95); pro Tick werden nur marksPerRun davon
// abgearbeitet, ab der zuletzt vollstaendig verarbeiteten Marke (checkpoint_json.last_mark_index).
// "DB: Tages-Item auf running setzen" (Postgres-UPDATE ohne RETURNING) hat das Item-JSON durch
// sein eigenes Ergebnis ersetzt - der eigentliche Tages-Item-Kontext kommt deshalb explizit vom
// Node VOR dem UPDATE (gleiche Bugklasse wie mehrfach in Workflow 15 dokumentiert).
const it = $('Baue Tages-Item-Kontext').all()[0].json;

function parseJsonField(v, fallback) {
  if (v === null || v === undefined) return fallback;
  if (typeof v === 'object') return v;
  try { return JSON.parse(v); } catch (e) { return fallback; }
}
const checkpoint = parseJsonField(it.checkpoint_json, { last_mark_index: -1, article_count: 0 });
const lastMarkIndex = Number.isInteger(checkpoint.last_mark_index) ? checkpoint.last_mark_index : -1;

// FIX 2026-08-17 (2. Iteration): adaptive Batchgroesse (AIMD, siehe Git-Historie) wieder
// zurueckgebaut - Nutzer-Entscheidung: immer nur 1 Marke pro Tick verarbeiten (schliesst das
// Speicher-Crash-Risiko bei groesseren Batches komplett aus), dafuer feuert der Trigger jetzt
// alle 15s statt alle 6min (siehe "Trigger: News-Worker"). Tempo stellt sich dadurch von selbst
// auf die tatsaechliche Verarbeitungsdauer pro Marke ein, ohne Crash-Erkennung noetig zu haben.
const marksPerRun = 1;

const probeWindowMin = Math.max(1, Number(it._probe_window_min || 5));

const startMark = lastMarkIndex + 1;
const endMark = Math.min(95, startMark + marksPerRun - 1);

if (startMark > 95) {
  // Sollte normalerweise nicht vorkommen (Item waere dann schon 'completed') - trotzdem robust
  // behandeln statt die Kette abbrechen zu lassen: Sentinel-Item ohne echte Marke durchreichen.
  return [{ json: { mark_index: -1, offset_min: 0, url: null, ts: null, _all_marks_done: true,
    _day: it.period_from, _job_id: it._job_id, _item_id: it.id, _request_delay_ms: it._request_delay_ms,
    _max_retries: it._max_retries, _attempt: Number(it.attempt || 0) + 1, _checkpoint: checkpoint } }];
}

// period_from kommt aus einer DATE-Spalte als voller ISO-Zeitstempel zurueck (gleiche
// Eigenheit wie in Workflow 15 bei period_from/period_to) - auf reines Datum kuerzen.
const day = String(it.period_from).slice(0, 10);
const dayStart = new Date(day + 'T00:00:00Z');

function fmtTs(d) {
  const p = n => String(n).padStart(2, '0');
  return '' + d.getUTCFullYear() + p(d.getUTCMonth() + 1) + p(d.getUTCDate()) + p(d.getUTCHours()) + p(d.getUTCMinutes()) + '00';
}

const out = [];
for (let mark = startMark; mark <= endMark; mark++) {
  const markMinutes = mark * 15;
  for (let offset = 1; offset <= probeWindowMin; offset++) {
    const ts = new Date(dayStart.getTime() + (markMinutes + offset) * 60000);
    out.push({
      json: {
        mark_index: mark, offset_min: offset, ts: fmtTs(ts),
        url: 'http://data.gdeltproject.org/gdeltv3/gal/' + fmtTs(ts) + '.gal.json.gz',
        _all_marks_done: false, _day: day, _job_id: it._job_id, _item_id: it.id,
        _request_delay_ms: it._request_delay_ms, _max_retries: it._max_retries,
        _attempt: Number(it.attempt || 0) + 1, _checkpoint: checkpoint, _end_mark_this_tick: endMark
      }
    });
  }
}
return out;

// Fasst alle Kandidaten-Antworten dieses Ticks pro Marke zusammen und waehlt je Marke den
// ersten Treffer (kleinster offset_min mit HTTP 200) aus - GDELT-Dateien erscheinen empirisch
// 1-4 Minuten nach der Marke, nicht zu einem fixen Versatz (siehe Konzeptdoc Abschnitt 8.4),
// deshalb mehrere Kandidaten pro Marke statt eines einzelnen fixen Zeitstempels.
//
// "HTTP: GDELT-Kandidat abrufen" ersetzt mit fullResponse:true das Item-JSON komplett durch
// {statusCode, headers} - die urspruenglichen Kontextfelder (mark_index/_day/...) sind darin
// NICHT mehr enthalten (gleiche "Node ueberschreibt Item"-Bugklasse wie bei Postgres-UPDATEs
// ohne RETURNING, hier aber beim HTTP-Node - live bestaetigt am 2026-08-03, Execution 25577:
// alle 60 Kandidaten wurden faelschlich unter mark_index=undefined in eine einzige Gruppe
// zusammengefasst). Deshalb den Kontext explizit vom Vorgaenger-Node per Index zurueckholen,
// nicht aus dem HTTP-Node-Output selbst - Itemreihenfolge/-anzahl bleibt bei einem einfachen
// Item-fuer-Item-Node wie httpRequest erhalten (kein Fan-in/Fan-out).
const candidates = $('Baue Marken-Kandidaten').all().map(i => i.json);
const httpResults = $input.all();

const byMark = new Map();
for (let i = 0; i < httpResults.length; i++) {
  const ctx = candidates[i];
  const httpItem = httpResults[i];
  const statusCode = httpItem.json ? httpItem.json.statusCode : undefined;
  const mark = ctx.mark_index;
  if (!byMark.has(mark)) byMark.set(mark, []);
  byMark.get(mark).push({ ctx, statusCode, binary: httpItem.binary });
}

const out = [];
for (const [mark, candidatesForMark] of byMark.entries()) {
  candidatesForMark.sort((a, b) => a.ctx.offset_min - b.ctx.offset_min);
  const hit = candidatesForMark.find(c => Number(c.statusCode) === 200 && c.binary && Object.keys(c.binary).length > 0);
  const ctx0 = candidatesForMark[0].ctx;
  if (hit) {
    out.push({ json: { mark_index: mark, _day: ctx0._day, _job_id: ctx0._job_id, _item_id: ctx0._item_id, _has_data: true }, binary: hit.binary });
  } else {
    out.push({ json: { mark_index: mark, _day: ctx0._day, _job_id: ctx0._job_id, _item_id: ctx0._item_id, _has_data: false, articles: [] } });
  }
}
return out;

// GDELT Article List: gzip-komprimierte JSON-NL-Datei (ein JSON-Objekt pro Zeile), Felder
// date/url/domain/outletName/outletLogo/outletTwitter/title/image/desc/lang/author - kein
// Volltext (siehe Konzeptdoc Abschnitt 8.4).
// Der Compression-Node benennt sein Ausgabe-Binaerfeld nicht "data" (trotz binaryPropertyOutput
// in den Node-Parametern), sondern "<outputPrefix>_<index>" (hier beobachtet: "file_0") - live
// bestaetigt am 2026-08-03 (Execution 25506). Ausserdem laeuft diese n8n-Instanz mit
// dateisystembasierter Binaerdaten-Ablage (nicht "memory"-Modus) - binary.<feld>.data ist dann
// KEIN inline-Base64-String, sondern nur Metadaten mit einer Datei-Referenz-ID; der tatsaechliche
// Inhalt muss ueber this.helpers.getBinaryDataBuffer() geholt werden, ebenfalls live bestaetigt
// (Execution 25557: "Buffer.from() ... Received undefined" beim direkten .data-Zugriff).
const binKey = Object.keys($binary || {})[0];
if (!binKey) {
  return { json: { mark_index: $json.mark_index, _day: $json._day, _job_id: $json._job_id, _item_id: $json._item_id, _has_data: false, articles: [] } };
}
const buffer = await this.helpers.getBinaryDataBuffer($itemIndex, binKey);
const text = buffer.toString('utf-8');
const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
const articles = [];
for (const line of lines) {
