}
return { json: { mark_index: $json.mark_index, _day: $json._day, _job_id: $json._job_id, _item_id: $json._item_id, _has_data: true, articles } };

function pgStr(v) {
  return v === null || v === undefined
    ? 'NULL'
    : `'${String(v).replace(/'/g, "''")}'`;
}

function pgNum(v) {
  return (
    v === null ||
    v === undefined ||
    v === '' ||
    isNaN(Number(v))
  )
    ? 'NULL'
    : Number(v);
}

function pgBool(v) {
  return v === null || v === undefined
    ? 'NULL'
    : (v ? 'TRUE' : 'FALSE');
}

function pgJsonb(v) {
  return v === null || v === undefined
    ? "'[]'::jsonb"
