    .trim()
    .toLowerCase();

  if (!language) return true;

  return ALLOWED_LANGUAGES.has(language);
}


// -----------------------------------------------------------------------------
// Unicode-sicheres Wort-Matching
// -----------------------------------------------------------------------------

function escapeRegex(s) {
  return String(s).replace(
    /[.*+?^${}()|[\]\\]/g,
    '\\$&'
  );
}

function containsWholeWord(haystack, needle) {
  const searchTerm = String(needle || '').trim();

  if (searchTerm.length < 2) return false;

  const pattern =
    '(?:^|[^\\p{L}\\p{N}])' +
    escapeRegex(searchTerm) +
    '(?![\\p{L}\\p{N}])';

  const regex = new RegExp(pattern, 'iu');

  return regex.test(String(haystack || ''));
}


// -----------------------------------------------------------------------------
// Aktienmatching
//
// Kurze Aliase mit maximal vier Zeichen werden ausschließlich im Titel
// akzeptiert. Das reduziert Falschtreffer durch Kürzel wie SAP, RWE und EON.
//
// Längere und damit meist eindeutigere Namen dürfen auch in der Beschreibung
// vorkommen.
// -----------------------------------------------------------------------------

function matchInstruments(title, description) {
  const matches = [];

  const titleText = String(title || '');
  const fullText = [
    titleText,
    String(description || '')
  ].join(' ');

  for (const instrument of instruments) {
    const aliases = parseJsonField(
      instrument.aliases_json,
      []
    );

    const excludes = parseJsonField(
      instrument.exclude_patterns_json,
      []
    );

    const searchTerms = [
      instrument.name,
      ...aliases
    ].filter(Boolean);

    const hasHit = searchTerms.some(term => {
      const normalizedTerm = String(term).trim();

      if (!normalizedTerm) return false;

      // Kurze Kürzel und Aliase nur im Nachrichtentitel zulassen.
      if (normalizedTerm.length <= 4) {
        return containsWholeWord(
          titleText,
          normalizedTerm
        );
      }

      // Längere Firmennamen auch in der Beschreibung suchen.
      return containsWholeWord(
        fullText,
        normalizedTerm
      );
    });

    if (!hasHit) continue;

    const isExcluded = excludes.some(term =>
      containsWholeWord(fullText, term)
    );

    if (isExcluded) continue;

    matches.push(
      String(instrument.ticker).trim()
    );
  }

  return [...new Set(matches)];
}
function findActiveExclusion(ticker, title, content) {
  const inst = instruments.find(i => i.ticker === ticker);
  if (!inst) return null;
  const rules = parseJsonField(inst.active_exclusions_json, []);
  for (const rule of rules) {
    if (!rule || !rule.pattern || !['phrase','exact_phrase'].includes(rule.pattern_type)) continue;
    const scope = rule.match_scope || 'title';
    const haystack = scope === 'title' ? String(title || '') : String(title || '') + '\n' + String(content || '');
    if (haystack.toLocaleLowerCase('de-DE').includes(String(rule.pattern).toLocaleLowerCase('de-DE'))) return rule;
  }
  return null;
}


