];

function testPattern(pattern, text) {
  pattern.lastIndex = 0;
  return pattern.test(text);
}

function macroScore(text) {
  let score = 0;
  let strongHits = 0;
  let broadHits = 0;

  for (const pattern of STRONG_MACRO_PATTERNS) {
    if (testPattern(pattern, text)) {
      strongHits += 1;
      score += 3;
    }
  }

  for (const pattern of BROAD_MARKET_PATTERNS) {
    if (testPattern(pattern, text)) {
      broadHits += 1;
      score += 1;
    }
  }

  return {
    score,
    strongHits,
    broadHits
  };
}


// -----------------------------------------------------------------------------
// Titel für die Deduplizierung normalisieren
