function normalizeTitle(title) {
  return String(title || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 180);
}


// -----------------------------------------------------------------------------
// Artikel klassifizieren
// -----------------------------------------------------------------------------

function isAiValidationSample(newsKey, ruleId, percent) {
  const limit = Math.max(0, Math.min(100, Number(percent) || 0));
  let hash = 2166136261;
  const value = String(newsKey || '') + '|' + String(ruleId || '');
  for (let i = 0; i < value.length; i++) { hash ^= value.charCodeAt(i); hash = Math.imul(hash, 16777619); }
  return (hash >>> 0) % 100 < limit;
}

const stockCandidates = [];
const exclusionHits = [];
const macroCandidates = [];

for (const article of articles) {
  if (!isAllowedLanguage(article.lang)) {
    continue;
  }

  const title = String(article.title || '');
  const description = String(article.desc || '');
  const text = `${title} ${description}`.trim();

  if (!text) continue;

  const tickerMatchesBeforeExclusions = matchInstruments(title, description);
  const effectiveTickerMatches = [];
  for (const ticker of tickerMatchesBeforeExclusions) {
    const rule = findActiveExclusion(ticker, article.title, article.desc);
    const inst = instruments.find(i => i.ticker === ticker);
    const auditOnly = inst && inst.exclusions_audit_only === true;
    const validationSample = rule && !auditOnly && itemCtx._dry_run !== true && isAiValidationSample(article.url, rule.id, inst.exclusion_ai_sample_percent);
    if (rule) {
      exclusionHits.push({ news_key: String(article.url).trim(), ticker, rule_id: rule.id, pattern: rule.pattern, title: article.title, dry_run: auditOnly || itemCtx._dry_run === true || validationSample });
      // Audit-Modus, Import-Dry-Run und die kontrollierte KI-Stichprobe behalten den Ticker.
      if (auditOnly || itemCtx._dry_run === true || validationSample) effectiveTickerMatches.push(ticker);
    } else effectiveTickerMatches.push(ticker);
  }
  const tickerMatches = effectiveTickerMatches;

  if (tickerMatches.length === 1) {
    stockCandidates.push({
      news_key: String(article.url).trim(),
      title: article.title,
      url: article.url,
      source: article.domain || article.outletName || null,
      published_at: article.date || null,
      language: article.lang || null,
      raw_content: article.desc || null,
      linked_tickers: tickerMatches,
      is_general_market: false,
      ticker_match_status: 'matched',
      ambiguous_candidates: [],
      normalized_title: normalizeTitle(article.title)
    });

    continue;
  }

  if (tickerMatches.length > 1) {
    stockCandidates.push({
      news_key: String(article.url).trim(),
      title: article.title,
      url: article.url,
      source: article.domain || article.outletName || null,
      published_at: article.date || null,
      language: article.lang || null,
      raw_content: article.desc || null,
      linked_tickers: [],
      is_general_market: false,
      ticker_match_status: 'ambiguous',
      ambiguous_candidates: tickerMatches,
      normalized_title: normalizeTitle(article.title)
    });

    continue;
  }

  if (tickerMatchesBeforeExclusions.length > 0 && tickerMatches.length === 0) {
    stockCandidates.push({ news_key:String(article.url).trim(),title:article.title,url:article.url,source:article.domain||article.outletName||null,published_at:article.date||null,language:article.lang||null,raw_content:article.desc||null,linked_tickers:[],is_general_market:false,ticker_match_status:'none',ambiguous_candidates:[],normalized_title:normalizeTitle(article.title) });
    continue;
  }

  const macro = macroScore(text);

  const isRelevantMacro =
    macro.strongHits >= 1 ||
    macro.broadHits >= 2;

  if (!isRelevantMacro) {
    continue;
  }

  macroCandidates.push({
    news_key: String(article.url).trim(),
    title: article.title,
    url: article.url,
    source: article.domain || article.outletName || null,
    published_at: article.date || null,
    language: article.lang || null,
    raw_content: article.desc || null,
    linked_tickers: [],
    is_general_market: true,
    ticker_match_status: 'none',
    ambiguous_candidates: [],
