for (const candidate of stockCandidates) {
  const tickerKey = candidate.ticker_match_status === 'matched'
    ? candidate.linked_tickers.slice().sort().join(',')
    : candidate.ambiguous_candidates.slice().sort().join(',');

  const titleKey =
    candidate.normalized_title ||
    String(candidate.news_key).toLowerCase();

  const dedupKey = `${tickerKey}|${titleKey}`;

  if (seenStockTitles.has(dedupKey)) {
    continue;
  }

  seenStockTitles.add(dedupKey);

  uniqueStockRows.push({
    news_key: candidate.news_key,
    title: candidate.title,
    url: candidate.url,
    source: candidate.source,
    published_at: candidate.published_at,
    language: candidate.language,
    raw_content: candidate.raw_content,
    linked_tickers: candidate.linked_tickers,
    is_general_market: candidate.is_general_market,
    ticker_match_status: candidate.ticker_match_status,
    ambiguous_candidates: candidate.ambiguous_candidates
  });
}


// -----------------------------------------------------------------------------
// Makronachrichten priorisieren und nach normalisiertem Titel deduplizieren
// -----------------------------------------------------------------------------

macroCandidates.sort((a, b) => {
  if (b.macro_score !== a.macro_score) {
    return b.macro_score - a.macro_score;
  }

  return (
    new Date(b.published_at || 0).getTime() -
    new Date(a.published_at || 0).getTime()
  );
});

const uniqueMacroCandidates = [];
